pub(crate) fn remove_unused_positional_arguments(
    &mut self,
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let unused_arguments = self.unused_positional.clone();
    let source_code = locator.slice(call);
    transform_expression(source_code, stylist, |mut expression| {
        let call = match_call_mut(&mut expression)?;

        // Remove any unused arguments.
        let mut index = 0;
        call.args.retain(|_| {
            let is_unused = unused_arguments.contains(&index);
            index += 1;
            !is_unused
        });

        // If we removed the final argument, the `format` call is a no-op, so replace the
        // entire call with its receiver.
        if call.args.is_empty() {
            if let libcst_native::Expression::Attribute(attribute) = &*call.func {
                return Ok((*attribute.value).clone());
            }
        }

        Ok(expression)
    })
    .map(|output| Edit::range_replacement(output, call.range()))

