input.newString:
// If every argument is being removed and there are no keyword arguments, the call
// itself may be a no-op, so replace it with its receiver. For example,
// `"Hello".format("world")` becomes `"Hello"`.
if call.arguments.keywords.is_empty()
    && !call.arguments.args.is_empty()
    && call
        .arguments
        .args
        .iter()
        .enumerate()
        .all(|(index, _)| unused_arguments.contains(&index))
{
    if let ast::Expr::Attribute(attribute) = &*call.func {
        // Only drop the call when the receiver is a string literal without any braces;
        // otherwise, removing the call would skip escaping or field processing.
        if let ast::Expr::StringLiteral(literal) = &*attribute.value {
            let format_string = literal.value.to_str();
            if !format_string.contains('{') && !format_string.contains('}') {
                return Ok(Edit::range_replacement(
                    locator.slice(attribute.value.range()).to_string(),
                    call.range(),
                ));
            }
        }
    }
}

